def average(scores):
    """Return the mean of a non-empty list of numbers."""
    return sum(scores) / len(scores)


def letter_grade(avg):
    if avg >= 90:
        return "A"
    elif avg >= 80:
        return "B"
    elif avg >= 70:
        return "C"
    else:
        return "Below C"


students = {"Ana": [92, 88, 95], "Ben": [78, 85, 80]}
for name, scores in students.items():
    avg = average(scores)
    print(f"{name}: {avg:.1f} ({letter_grade(avg)})")

