def parse_quantity(text):
    value = int(text)
    if not 1 <= value <= 99:
        raise ValueError("quantity must be 1 to 99")
    return value


def test_valid():
    assert parse_quantity("5") == 5


def test_boundary():
    assert parse_quantity("99") == 99


def test_invalid():
    with pytest.raises(ValueError):
        parse_quantity("0")
